const input = $json;
const candidates = Array.isArray(input.fact_candidates) ? input.fact_candidates : [];
const currentFacts = Array.isArray(input.current_facts) ? input.current_facts : [];
const allowedKeys = new Set([
  'service_interest','event_date','event_start_time','locality','event_type',
  'guest_count','venue_name','venue_address','customer_name','customer_email',
  'customer_phone','art_theme','art_colors','payment_expectation'
]);
const allowedStatuses = new Set(['known','derived','verified','conflict']);
const allowedSources = new Set(['customer','human','rule','calculation','integration','migration','agent']);
const operations = [];
const conflicts = [];
const ignored = [];

for (const candidate of candidates) {
  if (!allowedKeys.has(candidate.fact_key)) {
    ignored.push({fact_key:candidate.fact_key ?? null, reason_code:'FACT_KEY_NOT_ALLOWED'});
    continue;
  }
  if (!allowedStatuses.has(candidate.fact_status ?? 'known')) {
    ignored.push({fact_key:candidate.fact_key, reason_code:'FACT_STATUS_INVALID'});
    continue;
  }
  if (!allowedSources.has(candidate.source_type ?? 'customer')) {
    ignored.push({fact_key:candidate.fact_key, reason_code:'FACT_SOURCE_INVALID'});
    continue;
  }

  const current = currentFacts.find((fact) => fact.fact_key === candidate.fact_key && fact.is_current !== false);
  const same = current ? JSON.stringify(current.fact_value) === JSON.stringify(candidate.fact_value) : false;
  if (same) {
    ignored.push({fact_key:candidate.fact_key, reason_code:'FACT_UNCHANGED'});
    continue;
  }

  const critical = Boolean(candidate.critical || current?.critical);
  const sourceIsAuthoritative = ['customer','human','integration','rule','calculation'].includes(candidate.source_type ?? 'customer');

  if (current && critical && !sourceIsAuthoritative) {
    conflicts.push({
      fact_key:candidate.fact_key,
      current_value:current.fact_value,
      candidate_value:candidate.fact_value,
      reason_code:'CRITICAL_FACT_CONFLICT'
    });
    continue;
  }

  operations.push({
    action:'RECORD_EVENT_FACT',
    customer_event_id:input.customer_event_id ?? null,
    source_event_id:input.source_event_id ?? null,
    fact_key:candidate.fact_key,
    fact_value:candidate.fact_value,
    fact_status:candidate.fact_status ?? 'known',
    source_type:candidate.source_type ?? 'customer',
    source_ref:candidate.source_ref ?? null,
    confidence:candidate.confidence ?? null,
    critical,
    supersedes_fact_id:current?.id ?? null
  });
}

if (conflicts.length > 0) {
  operations.push({action:'ENABLE_HUMAN_LOCK',reason_code:'CRITICAL_FACT_CONFLICT'});
  operations.push({action:'CREATE_HUMAN_TASK',reason_code:'CRITICAL_FACT_CONFLICT'});
}

return {
  json:{
    contract_version:'1.0.0',
    customer_event_id:input.customer_event_id ?? null,
    operations,
    conflicts,
    ignored,
    result_event_type: conflicts.length > 0 ? 'fact_conflict_detected' : 'facts_commit_planned',
    blockers: conflicts.length > 0 ? ['CRITICAL_FACT_CONFLICT'] : []
  }
};
